const API="https://tillbot.onrender.com", $=id=>document.getElementById(id);
// Keep the app shell inside iOS Safari's visible viewport when its keyboard opens.
const syncVisualViewport=()=>{if(window.visualViewport&&matchMedia("(max-width: 820px)").matches){document.documentElement.style.setProperty("--tb-visual-height",Math.round(window.visualViewport.height)+"px")}else{document.documentElement.style.removeProperty("--tb-visual-height")}};
syncVisualViewport();window.visualViewport?.addEventListener("resize",syncVisualViewport);window.addEventListener("orientationchange",()=>setTimeout(syncVisualViewport,180));let token=localStorage.getItem("tb-token"),user=null,registerMode=false,activeId=null,chats=[],busy=false,history=[],photoData=null,photoMime="image/jpeg";
const headers=()=>({"Content-Type":"application/json",...(token?{Authorization:"Bearer "+token}:{})});
function authMode(reg){
 registerMode=reg;
 $("tabLogin").classList.toggle("selected",!reg);$("tabRegister").classList.toggle("selected",reg);
 $("tabLogin").setAttribute("aria-selected",String(!reg));$("tabRegister").setAttribute("aria-selected",String(reg));
 $("authTitle").textContent=reg?"Erstelle dein Konto.":"Dein Platz für neue Ideen.";
 $("authDescription").textContent=reg?"Ein Benutzername, ein sicheres Passwort – und dein eigener KI-Bereich.":"Melde dich an und setze deine Chats genau dort fort, wo du aufgehört hast.";
 $("authSubmitText").textContent=reg?"Konto erstellen":"Anmelden";
 $("password").autocomplete=reg?"new-password":"current-password";
 $("passwordHint").textContent=reg?"Mindestens 10 Zeichen":"Dein Kontopasswort";
 $("confirmPasswordRow").classList.toggle("hidden",!reg);
 $("confirmPassword").required=reg;
 $("usernameHint").textContent=reg?"3–20 Zeichen: Kleinbuchstaben, Zahlen und Unterstrich.":"Gib deinen Benutzernamen ein.";
 $("authMsg").textContent="";
}
window.tillbotAuthMode=authMode;$("tabLogin").onclick=()=>authMode(false);$("tabRegister").onclick=()=>authMode(true);
async function authRequest(path,body){let last;for(let attempt=0;attempt<2;attempt++){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),60000);try{const response=await fetch(API+path,{method:"POST",headers:headers(),body:JSON.stringify(body),signal:controller.signal});const raw=await response.text();let data={};try{data=raw?JSON.parse(raw):{}}catch{}if(response.ok)return data;const err=Error(data.error||data.answer||"HTTP "+response.status);err.status=response.status;if(attempt===0&&[502,503,504].includes(response.status)){last=err;await new Promise(r=>setTimeout(r,1800));continue}throw err}catch(e){last=e;if(attempt===0&&(!e.status||e.name==="AbortError")){await new Promise(r=>setTimeout(r,1800));continue}if(e.name==="AbortError")throw Error("Der Server braucht zu lange zum Aufwachen. Bitte 1 Minute warten und erneut anmelden.");throw e}finally{clearTimeout(timer)}}throw last||Error("Anmeldung fehlgeschlagen")}

async function checkAuthStatus(){
 const msg=$("authMsg");
 try{
  const response=await fetch(API+"/api/auth/status",{cache:"no-store"});
  if(!response.ok)throw Error("HTTP "+response.status);
  const status=await response.json();
  if(!status.databaseReady){msg.textContent="Anmeldung gerade nicht verfügbar: Die Datenbank antwortet momentan nicht.";return}
  msg.textContent="";
 }catch{
  msg.textContent="TILLBOT-Server nicht erreichbar. Bitte später erneut versuchen.";
 }
}
checkAuthStatus();
window.tillbotAuthSubmit=async()=>{
 const b=$("authSubmit"),username=$("username").value.trim().toLowerCase(),password=$("password").value;
 if(!/^[a-z0-9_]{3,20}$/.test(username)){ $("authMsg").textContent="Benutzername: 3–20 Zeichen (a–z, 0–9, _).";$("username").focus();return; }
 if(registerMode){
  if(password.length<10||password.length>128){$("authMsg").textContent="Das Passwort muss 10–128 Zeichen haben.";$("password").focus();return;}
  if(password!==$("confirmPassword").value){$("authMsg").textContent="Die Passwörter stimmen nicht überein.";$("confirmPassword").focus();return;}
 }else if(!password){$("authMsg").textContent="Bitte gib dein Passwort ein.";$("password").focus();return;}
 b.disabled=true;$("authMsg").textContent=registerMode?"Dein Konto wird sicher erstellt …":"Du wirst sicher angemeldet …";
 try{
  const path=registerMode?"/api/register":"/api/login";
  const d=await authRequest(path,{username,password,website:$("website").value});
  $("website").value="";
  token=d.token;user=d.user;localStorage.setItem("tb-token",token);
  $("authMsg").textContent="Erfolgreich! Dein Workspace wird geöffnet …";await start();
 }catch(e){
  $("authMsg").textContent=e.message||"Das hat nicht geklappt. Bitte versuche es erneut.";
 }finally{$("website").value="";b.disabled=false}
};
$("authSubmit").onclick=window.tillbotAuthSubmit;
$("password").onkeydown=e=>{if(e.key==="Enter")$("authSubmit").click()};
$("confirmPassword").onkeydown=e=>{if(e.key==="Enter")$("authSubmit").click()};
const passwordToggle=$("togglePassword");passwordToggle.onclick=()=>{const visible=$("password").type==="text";$("password").type=visible?"password":"text";passwordToggle.textContent=visible?"Anzeigen":"Verbergen";passwordToggle.setAttribute("aria-pressed",String(!visible));passwordToggle.setAttribute("aria-label",visible?"Passwort anzeigen":"Passwort verbergen")};
async function loadSystemNotice(){try{const n=await fetch(API+"/api/notifications",{cache:"no-store"}).then(r=>r.json());const el=$("systemNotice"),txt=$("systemNoticeText");const text=[n.announcement,n.notice].filter(Boolean).join(" · ");if(text){txt.textContent=text;el.className="systemNotice "+(n.level==="critical"?"critical":"warning");el.dataset.notice=text;if(localStorage.getItem("tb-dismissed-notice")===text)el.classList.add("hidden")}else{txt.textContent="";el.className="systemNotice hidden";el.dataset.notice=""}}catch{}}$("dismissNotice").onclick=()=>{localStorage.setItem("tb-dismissed-notice",$("systemNotice").dataset.notice||"");$("systemNotice").classList.add("hidden")};
async function checkMaintenance(){try{const m=await fetch(API+"/api/maintenance").then(r=>r.json());$("maintenanceText").textContent=m.message||"TILLBOT wird gerade gewartet.";const isAdmin=user&&user.role==="admin";$("maintenanceScreen").classList.toggle("hidden",!m.enabled||isAdmin);document.body.classList.toggle("maintenanceActive",m.enabled&&!isAdmin);return m}catch{return {enabled:false}}}
async function start(){if(!token){user=null;$("auth").classList.remove("hidden");$("app").classList.add("hidden");await checkMaintenance();return}let d;try{d=await api("/api/me")}catch(e){if(e.status===401){token=null;localStorage.removeItem("tb-token");user=null}$("auth").classList.remove("hidden");$("app").classList.add("hidden");$("authMsg").textContent=e.status===401?"Session abgelaufen. Bitte erneut anmelden.":"Serververbindung fehlgeschlagen: "+e.message+" · Seite nach Wiederherstellung neu laden.";await checkMaintenance();return}user=d.user;$("auth").classList.add("hidden");$("app").classList.remove("hidden");$("who").textContent="@"+user.username;$("sideUser").textContent=user.username;$("admin").classList.toggle("hidden",user.role!=="admin");$("studioShortcut").classList.toggle("hidden",user.role!=="admin");await checkMaintenance();await loadSystemNotice();try{await loadChats()}catch(e){$("history").textContent="Chats konnten nicht geladen werden: "+e.message}await loadQuota()}
async function loadChats(){chats=await api("/api/chats");const hist=$("history");let search=$("chatSearch");if(!search){search=document.createElement("input");search.id="chatSearch";search.type="search";search.placeholder="Chats durchsuchen…";search.setAttribute("aria-label","Chats durchsuchen");search.style.cssText="width:100%;box-sizing:border-box;margin:8px 0;padding:10px;border-radius:10px;background:var(--panel, #171b29);color:var(--text, #fff);border:1px solid var(--border, #30364a)";hist.before(search);search.addEventListener("input",()=>renderChatList())}renderChatList();if(activeId&&chats.some(c=>c.id===activeId))await openChat(activeId);else{activeId=null;history=[];render()}}function renderChatList(){const hist=$("history");hist.innerHTML="";let exportAll=$("exportAllChats");if(!exportAll){exportAll=document.createElement("button");exportAll.id="exportAllChats";exportAll.type="button";exportAll.textContent="⬇ Alle Chats exportieren (JSON)";exportAll.style.cssText="width:100%;margin:4px 0 10px;padding:9px;border-radius:10px";hist.before(exportAll);exportAll.onclick=async()=>{exportAll.disabled=true;exportAll.textContent="Export wird vorbereitet…";try{const all=await Promise.all(chats.map(async c=>{const d=await api("/api/chats/"+c.id);return {id:c.id,title:c.title,history:d.chat.history||[]}}));const blob=new Blob([JSON.stringify({app:"TILLBOT",exportedAt:new Date().toISOString(),chats:all},null,2)],{type:"application/json"});const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="tillbot-chats-"+new Date().toISOString().slice(0,10)+".json";a.click();URL.revokeObjectURL(url);exportAll.textContent="Export fertig ✓"}catch(e){alert("Export fehlgeschlagen: "+e.message);exportAll.textContent="⬇ Alle Chats exportieren (JSON)"}finally{exportAll.disabled=false}}}const q=($("chatSearch")?.value||"").trim().toLowerCase();chats.filter(c=>String(c.title||"").toLowerCase().includes(q)).forEach(c=>{const wrap=document.createElement("div");wrap.className="historyItem";const b=document.createElement("button");b.className="historyOpen";b.textContent="☁  "+c.title;b.title=c.title;b.onclick=()=>openChat(c.id);const actions=document.createElement("div");actions.className="historyActions";const rename=document.createElement("button");rename.type="button";rename.textContent="✎";rename.title="Chat umbenennen";rename.onclick=async e=>{e.stopPropagation();const title=prompt("Neuer Chatname:",c.title);if(!title||!title.trim())return;try{await api("/api/chats/"+c.id,{method:"PUT",body:JSON.stringify({title:title.trim().slice(0,100),history:(activeId===c.id?history:(await api("/api/chats/"+c.id)).chat.history)})});await loadChats()}catch(err){alert(err.message)}};const del=document.createElement("button");del.type="button";del.textContent="×";del.title="Chat löschen";del.onclick=async e=>{e.stopPropagation();if(!confirm('"'+c.title+'" wirklich löschen?'))return;try{await api("/api/chats/"+c.id,{method:"DELETE"});if(activeId===c.id){activeId=null;history=[];render()}await loadChats()}catch(err){alert(err.message)}};actions.append(rename,del);wrap.append(b,actions);$("history").append(wrap)})}async function openChat(id){let d=await api("/api/chats/"+id);activeId=id;history=d.chat.history||[];render();$("sidebar").classList.remove("open")}
function renderPlainAssistant(root,text){
 const lines=String(text||"").split("\n");let list=null,paragraph=[];
 const flush=()=>{if(paragraph.length){const p=document.createElement("p");p.textContent=paragraph.join(" ");p.className="assistantParagraph";root.append(p);paragraph=[]}};
 const closeList=()=>{if(list){root.append(list);list=null}};
 lines.forEach(line=>{
  const s=line.trim();if(!s){flush();closeList();return}
  const h=s.match(/^(#{1,3})\s+(.+)$/);if(h){flush();closeList();const el=document.createElement("h"+Math.min(4,h[1].length+1));el.className="assistantHeading";el.textContent=h[2];root.append(el);return}
  const source=s.match(/^\[([^\]]+)\]\((https:\/\/[^)]+)\)$/);
  if(source){flush();closeList();const link=document.createElement("a");link.href=source[2];link.textContent=source[1];link.target="_blank";link.rel="noopener noreferrer";link.className="assistantSourceLink";root.append(link);return}
  const bullet=s.match(/^[-*•]\s+(.+)$/),number=s.match(/^\d+[.)]\s+(.+)$/);
  if(bullet||number){flush();const ordered=!!number;if(list&&list.tagName!==(ordered?"OL":"UL"))closeList();if(!list)list=document.createElement(ordered?"ol":"ul");const li=document.createElement("li");li.textContent=(bullet||number)[1];list.append(li);return}
  closeList();paragraph.push(s)
 });flush();closeList();
}
function renderAssistant(root,text){
 const chunks=String(text||"").split("```");
 chunks.forEach((chunk,i)=>{
  if(i%2===0){if(chunk.trim())renderPlainAssistant(root,chunk);return}
  const nl=chunk.indexOf("\n"),lang=(nl<0?chunk:chunk.slice(0,nl)).trim().slice(0,24)||"code",code=nl<0?"":chunk.slice(nl+1).replace(/\s+$/,"");
  const card=document.createElement("section");card.className="codeCard";const head=document.createElement("div");head.className="codeHead";
  const label=document.createElement("span");label.textContent=lang;head.append(label);
  const copy=document.createElement("button");copy.type="button";copy.textContent="Kopieren";copy.onclick=async()=>{try{await navigator.clipboard.writeText(code);copy.textContent="Kopiert ✓";setTimeout(()=>copy.textContent="Kopieren",1400)}catch{copy.textContent="Nicht möglich"}};
  const down=document.createElement("button");down.type="button";down.textContent="Download";down.onclick=()=>{const ext=({javascript:"js",js:"js",typescript:"ts",ts:"ts",python:"py",py:"py",html:"html",css:"css",json:"json",java:"java",c:"c",cpp:"cpp",sql:"sql",bash:"sh",sh:"sh"})[lang.toLowerCase()]||"txt";const blob=new Blob([code],{type:"text/plain;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="tillbot-code."+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  head.append(copy,down);if(i===1){const zipBtn=document.createElement("button");zipBtn.type="button";zipBtn.textContent="ZIP";zipBtn.title="Alle Codeblöcke dieser Antwort als Projekt herunterladen";zipBtn.onclick=async()=>{if(!window.JSZip){alert("ZIP-Modul konnte nicht geladen werden.");return}zipBtn.disabled=true;zipBtn.textContent="…";try{const zip=new JSZip(),parts=String(text).split(String.fromCharCode(96,96,96));let n=0;for(let j=1;j<parts.length;j+=2){const p=parts[j],line=p.indexOf("\n"),language=(line<0?p:p.slice(0,line)).trim().toLowerCase(),body=(line<0?"":p.slice(line+1)).replace(/\s+$/,"");if(!body)continue;const ext=({javascript:"js",js:"js",typescript:"ts",ts:"ts",python:"py",py:"py",html:"html",css:"css",json:"json",java:"java",c:"c",cpp:"cpp",sql:"sql",bash:"sh",sh:"sh"})[language]||"txt";zip.file("datei-"+(++n)+"."+ext,body)}if(!n){zip.file("antwort.txt",String(text))}const blob=await zip.generateAsync({type:"blob"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="tillbot-projekt.zip";a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);zipBtn.textContent="ZIP ✓"}catch{zipBtn.textContent="Fehler"}finally{zipBtn.disabled=false}};head.append(zipBtn)}const pre=document.createElement("pre"),cb=document.createElement("code");cb.textContent=code;pre.append(cb);card.append(head,pre);root.append(card)
 });
}
function render(){let el=$("chat");el.innerHTML="";if(!history.length){el.innerHTML='<div class="welcome"><div class="cloud"><img src="./icons/tillbot.svg" alt="TILLBOT Wolke"></div><span class="eyebrow">DEIN KI-ASSISTENT</span><h1 id="homeTitle">Was möchtest du heute erschaffen?</h1><p id="homeSubtitleText" class="muted">Frag drauf los. Ideen, Wissen und Kreativität – alles an einem Ort.</p><div class="suggestions"><button data-prompt="Erkläre mir etwas Spannendes">✧ Lernen</button><button data-prompt="Hilf mir mit einer Idee">✧ Ideen</button><button data-prompt="Schreibe einen Text">✧ Schreiben</button><button data-prompt="Hilf mir beim Programmieren">⌘ Code</button><button data-prompt="Erstelle einen Lernplan">▤ Lernplan</button><button data-prompt="Fasse dieses Thema verständlich zusammen">☷ Zusammenfassen</button></div></div>';el.querySelectorAll("[data-prompt]").forEach(b=>b.onclick=()=>{$("prompt").value=b.dataset.prompt;$("prompt").focus()});return}history.forEach((m,index)=>{let div=document.createElement("div");div.className="bubble "+(m.role==="user"?"user":"bot");if(m.role==="assistant"){renderAssistant(div,m.content);const tools=document.createElement("div");tools.className="messageActions";const copy=document.createElement("button");copy.type="button";copy.textContent="⧉ Kopieren";copy.onclick=async()=>{try{await navigator.clipboard.writeText(m.content);copy.textContent="✓ Kopiert";setTimeout(()=>copy.textContent="⧉ Kopieren",1300)}catch{copy.textContent="Nicht verfügbar"}};tools.append(copy);const speak=document.createElement("button");speak.type="button";speak.textContent="🔊 Vorlesen";speak.title="KI-Antwort vorlesen";speak.onclick=()=>{if(!("speechSynthesis" in window)){speak.textContent="Nicht unterstützt";return}speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(m.content.replace(/```[\\s\\S]*?```/g,"Codeblock ausgelassen"));utter.lang="de-DE";utter.onstart=()=>speak.textContent="⏸ Spricht …";utter.onend=()=>speak.textContent="🔊 Vorlesen";utter.onerror=()=>speak.textContent="Vorlesen fehlgeschlagen";speechSynthesis.speak(utter)};tools.append(speak);if(index===history.length-1){const regen=document.createElement("button");regen.type="button";regen.textContent="↻ Neu antworten";regen.disabled=busy;regen.onclick=()=>{if(busy)return;history.pop();const lastUser=history.pop();if(!lastUser||lastUser.role!=="user")return;$("prompt").value=lastUser.content.replace(/ \\[Foto angehängt\\]$/,"");render();send()};tools.append(regen)}div.append(tools)}else div.textContent=m.content;el.append(div)});el.scrollTop=el.scrollHeight}
async function loadQuota(){const el=$("quotaStatus");if(!el)return;try{const q=await api("/api/usage");if(q.unlimited){el.textContent="Admin · unbegrenzte Nachrichten";el.className="quotaStatus adminQuota";if(!busy)$("send").disabled=false;return}if(q.blocked){el.textContent="Pause bis "+new Date(q.until).toLocaleString("de-DE");el.className="quotaStatus quotaBlocked";$("send").disabled=true;return}el.textContent="Tagesbudget: "+q.remaining+" von "+(q.limit||30)+" Nachrichten übrig";el.className="quotaStatus";if(!busy)$("send").disabled=false;}catch{el.textContent=""}}
async function send(){if(busy)return;let text=$("prompt").value.trim();if(!text&&!photoData)return;busy=true;$("send").disabled=true;$("prompt").value="";history.push({role:"user",content:text+(photoData?" [Foto angehängt]":"")});render();let wait=document.createElement("div");wait.className="bubble bot thinkingBubble";wait.innerHTML='<span class="thinkingLabel"><span class="thinkingOrb"></span><strong>Tailbot denkt nach</strong></span><span class="thinkingStatus">Nachricht wird vorbereitet …</span><span class="thinkingDots" aria-hidden="true"><i></i><i></i><i></i></span>';$("chat").append(wait);let statusTimer=setInterval(()=>{const s=wait.querySelector(".thinkingStatus");if(!s)return;const stages=["Nachricht wird analysiert …","Kontext wird geprüft …","Antwort wird formuliert …","Antwort wird verfeinert …"];s.textContent=stages[(Number(wait.dataset.stage||0)+1)%stages.length];wait.dataset.stage=String(Number(wait.dataset.stage||0)+1)},1800);try{if(!activeId){let c=await api("/api/chats",{method:"POST",body:JSON.stringify({title:text.slice(0,70)||"Neuer Chat"})});activeId=c.id}const payload={message:text,history:history.slice(0,-1),image:photoData?{data:photoData,mime:photoMime}:null,stream:true};const response=await fetch(API+"/api/chat",{method:"POST",headers:headers(),body:JSON.stringify(payload)});if(!response.ok){const er=await response.json();throw Error(er.error||er.answer||"HTTP "+response.status)}if(!response.body)throw Error("Streaming wird vom Browser nicht unterstützt.");const reader=response.body.getReader(),decoder=new TextDecoder();let pending="",answer="",finished=false;const statusEl=wait.querySelector(".thinkingStatus");if(statusEl)statusEl.textContent="Antwort wird generiert …";wait.querySelector(".thinkingDots")?.remove();while(true){const {done,value}=await reader.read();if(done)break;pending+=decoder.decode(value,{stream:true});const events=pending.split("\n\n");pending=events.pop()||"";for(const event of events){const line=event.split("\n").find(x=>x.startsWith("data:"));if(!line)continue;try{const data=JSON.parse(line.slice(5).trim());if(data.delta){answer+=data.delta;wait.textContent=answer}else if(data.done){finished=true}}catch{}}}if(!answer)throw Error("Die KI hat keine Antwort geliefert.");history.push({role:"assistant",content:answer});await loadQuota();photoData=null;$("photoPreview").classList.add("hidden");$("photoPreview").innerHTML="";await api("/api/chats/"+activeId,{method:"PUT",body:JSON.stringify({title:history.find(x=>x.role==="user")?.content?.slice(0,70)||"Chat",history})});await loadChats()}catch(e){history.push({role:"assistant",content:"Fehler: "+e.message}) ;await loadQuota()}finally{clearInterval(statusTimer);busy=false;if(!$("quotaStatus").classList.contains("quotaBlocked"))$("send").disabled=false;render()}}
