$("exportChat").onclick=()=>{if(!history.length){$("exportMsg").textContent="Dieser Chat ist noch leer.";return}const lines=history.map(m=>(m.role==="user"?"Du":"TILLBOT")+": "+m.content).join("\n\n");const blob=new Blob([lines],{type:"text/plain;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="tillbot-chat-"+new Date().toISOString().slice(0,10)+".txt";link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$("exportMsg").textContent="Chat wurde heruntergeladen."};
const homeDefaults={greeting:"Was möchtest du heute erschaffen?",subtitle:"Frag drauf los. Ideen, Wissen und Kreativität – alles an einem Ort.",accent:"blue",layout:"classic"};function applyHomeCustomize(){let cfg;try{cfg={...homeDefaults,...JSON.parse(localStorage.getItem("tb-home-custom")||"{}")}}catch{cfg=homeDefaults}const title=$("homeTitle"),sub=$("homeSubtitleText");if(title)title.textContent=cfg.greeting;if(sub)sub.textContent=cfg.subtitle;document.body.dataset.homeAccent=cfg.accent;document.body.dataset.homeLayout=cfg.layout;$("homeGreeting").value=cfg.greeting;$("homeSubtitle").value=cfg.subtitle;$("homeAccent").value=cfg.accent;$("homeLayout").value=cfg.layout}function saveHomeCustomize(){const cfg={greeting:$("homeGreeting").value.trim().slice(0,70)||homeDefaults.greeting,subtitle:$("homeSubtitle").value.trim().slice(0,160)||homeDefaults.subtitle,accent:["blue","mint","violet","rose"].includes($("homeAccent").value)?$("homeAccent").value:"blue",layout:["classic","minimal","focus"].includes($("homeLayout").value)?$("homeLayout").value:"classic"};localStorage.setItem("tb-home-custom",JSON.stringify(cfg));applyHomeCustomize();$("homeCustomizeMsg").textContent="Deine Startseite wurde gespeichert ✓"}$("saveHomeCustomize").onclick=saveHomeCustomize;$("resetHomeCustomize").onclick=()=>{localStorage.removeItem("tb-home-custom");applyHomeCustomize();$("homeCustomizeMsg").textContent="Standard wiederhergestellt."};applyHomeCustomize();$("settingsBtn").onclick=()=>{$("settingsDialog").showModal();loadMyTickets()};
