async function loadMetrics(){const el=$("serverMetrics");el.innerHTML="<p>Messwerte laden …</p>";try{const m=await api("/api/admin/metrics");const fmt=n=>{if(n<1024)return n+" B";if(n<1048576)return (n/1024).toFixed(1)+" KB";return (n/1048576).toFixed(1)+" MB"};el.innerHTML='<div class="metricGrid"><article><small>STATUS</small><strong style="color:#35d99c">● ONLINE</strong></article><article><small>CPU (Prozess)</small><strong>'+m.cpuProcessPercent+'%</strong></article><article><small>RAM (RSS)</small><strong>'+fmt(m.memory.rss)+'</strong></article><article><small>Heap</small><strong>'+fmt(m.memory.heapUsed)+' / '+fmt(m.memory.heapTotal)+'</strong></article><article><small>DB-Dateigröße</small><strong>'+fmt(m.databaseBytes)+'</strong></article><article><small>Uptime</small><strong>'+Math.floor(m.uptimeSeconds/3600)+' h '+Math.floor(m.uptimeSeconds%3600/60)+' min</strong></article><article><small>Accounts</small><strong>'+m.users+'</strong></article><article><small>Chats</small><strong>'+m.chats+'</strong></article><article><small>Node</small><strong>'+m.node+'</strong></article></div><p class="metricsNote">CPU bezieht sich auf den Node-Prozess. Messwerte sind Momentaufnahmen.</p>'}catch(e){el.textContent="Monitoring-Fehler: "+e.message}}async function loadDailyQuotaAdmin(){try{const q=await api("/api/admin/quota");$("dailyQuotaInput").value=q.limit;$("dailyQuotaMsg").textContent=""}catch(e){$("dailyQuotaMsg").textContent=e.message}}
