async function loadMaintenanceControl(){try{const m=await api("/api/maintenance");$("maintenanceAdminStatus").textContent=m.enabled?"● AKTIV – KI ist für Nutzer pausiert":"● AUS – KI ist verfügbar";$("maintenanceAdminStatus").className="maintenanceStatus "+(m.enabled?"isOn":"isOff");$("maintenanceAdminMessage").value=m.message||"";$("maintenanceToggle").textContent=m.enabled?"Wartungsmodus deaktivieren":"Wartungsmodus aktivieren";$("maintenanceToggle").dataset.enabled=String(m.enabled)}catch(e){$("maintenanceAdminStatus").textContent=e.message}}
