async function runSecurityAudit(){const el=$("securityAuditResult"),btn=$("runSecurityAudit");btn.disabled=true;el.textContent="Prüfung läuft …";try{const a=await api("/api/admin/security-audit");el.innerHTML="";const head=document.createElement("p");head.className="auditSummary";head.textContent=a.score+"/"+a.total+" Checks bestanden · "+new Date(a.checkedAt).toLocaleString("de-DE");el.append(head);a.checks.forEach(c=>{const row=document.createElement("div");row.className="auditRow "+(c.ok?"auditOk":"auditFail");const title=document.createElement("strong");title.textContent=(c.ok?"✓ ":"⚠ ")+c.name;const detail=document.createElement("small");detail.textContent=c.detail;row.append(title,detail);el.append(row)});const note=document.createElement("small");note.className="auditDisclaimer";note.textContent=a.note;el.append(note)}catch(e){el.textContent="Prüfung fehlgeschlagen: "+e.message}finally{btn.disabled=false}}
