// Admin command palette: every action uses existing admin-authenticated API endpoints.
const commandInput=$("adminCommand"),commandOutput=$("adminCommandOutput");
async function executeAdminCommand(){const raw=(commandInput.value||"").trim(),cmd=raw.toLowerCase();if(!cmd)return;commandOutput.textContent="> "+raw+"\n";commandInput.value="";try{switch(cmd){case"help":commandOutput.textContent+="Befehle: help · status · audit · maintenance on · maintenance off · shutdown · metrics · users";break;case"status":{const m=await api("/api/maintenance");commandOutput.textContent+=m.enabled?"Wartungsmodus AKTIV: "+m.message:"Systemstatus: normal";break}case"audit":await runSecurityAudit();commandOutput.textContent+="Sicherheitsprüfung im Audit-Bereich ausgeführt.";break;case"maintenance on":case"shutdown":{await api("/api/admin/maintenance",{method:"PUT",body:JSON.stringify({enabled:true,message:cmd==="shutdown"?"TILLBOT ist vorübergehend offline (Wartungsmodus).":"TILLBOT wird gerade gewartet. Bitte später erneut versuchen."})});commandOutput.textContent+="Wartungsmodus aktiviert. KI-Anfragen normaler Nutzer pausiert; Render-Prozess läuft weiter.";await loadMaintenanceControl();await checkMaintenance();break}case"maintenance off":{await api("/api/admin/maintenance",{method:"PUT",body:JSON.stringify({enabled:false})});commandOutput.textContent+="Wartungsmodus deaktiviert.";await loadMaintenanceControl();await checkMaintenance();break}case"metrics":await loadMetrics();commandOutput.textContent+="Metriken aktualisiert (siehe Systemmetriken).";break;case"users":await loadAdminUsers();commandOutput.textContent+="Benutzerliste aktualisiert.";break;default:commandOutput.textContent+="Unbekannter Befehl. help zeigt alle Befehle."}}catch(e){commandOutput.textContent+="Fehler: "+e.message+" (Admin-Login/API prüfen)"}}
$("runAdminCommand").onclick=executeAdminCommand;commandInput.addEventListener("keydown",e=>{if(e.key==="Enter")executeAdminCommand()});

const studioDefaults={title:"TILLBOT Control Center",accent:"ocean",density:"normal",metrics:true,security:true,users:true,tickets:true,quota:true,maintenance:true};function applyStudio(){let c;try{c={...studioDefaults,...JSON.parse(localStorage.getItem("tb-admin-studio")||"{}")}}catch{c=studioDefaults}$("studioTitle").value=c.title||studioDefaults.title;$("adminDashboardTitle").textContent=c.title||studioDefaults.title;Object.entries({studioAccent:c.accent,studioDensity:c.density}).forEach(([id,v])=>$(id).value=v);Object.entries({studioMetrics:c.metrics,studioSecurity:c.security,studioUsers:c.users,studioTickets:c.tickets,studioQuota:c.quota,studioMaintenance:c.maintenance}).forEach(([id,v])=>$(id).checked=v);$("adminDialog").dataset.studioAccent=c.accent;$("adminDialog").dataset.studioDensity=c.density;const sections={studioMetrics:"serverMetrics",studioSecurity:".securityAudit",studioUsers:".userAdmin",studioTickets:"#loadTickets",studioQuota:".quotaAdmin",studioMaintenance:".maintenanceAdmin"};Object.entries(sections).forEach(([key,sel])=>{const target=$(sel)||$("adminDialog").querySelector(sel);if(target){const section=target.matches("section")?target:target.closest("section");if(section)section.classList.toggle("studioHidden",!$(key).checked)}})}function saveStudio(){const c={title:$("studioTitle").value.trim().slice(0,45)||studioDefaults.title,accent:$("studioAccent").value,density:$("studioDensity").value,metrics:$("studioMetrics").checked,security:$("studioSecurity").checked,users:$("studioUsers").checked,tickets:$("studioTickets").checked,quota:$("studioQuota").checked,maintenance:$("studioMaintenance").checked};localStorage.setItem("tb-admin-studio",JSON.stringify(c));applyStudio();$("studioMsg").textContent="Admin Studio gespeichert ✓"}$("saveStudio").onclick=saveStudio;$("resetStudio").onclick=()=>{localStorage.removeItem("tb-admin-studio");applyStudio();$("studioMsg").textContent="Studio-Standard wiederhergestellt."};["studioAccent","studioDensity","studioMetrics","studioSecurity","studioUsers","studioTickets","studioQuota","studioMaintenance"].forEach(id=>$(id).addEventListener("change",applyStudio));$("studioInstall").onclick=()=>$("installApp").click();$("studioExport").onclick=()=>{const blob=new Blob([JSON.stringify(JSON.parse(localStorage.getItem("tb-admin-studio")||"{}"),null,2)],{type:"application/json"});const url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="tillbot-studio-settings.json";link.click();URL.revokeObjectURL(url)};$("studioImport").onclick=()=>$("studioImportFile").click();$("studioImportFile").onchange=async e=>{try{const cfg=JSON.parse(await e.target.files[0].text());if(!cfg||typeof cfg!=="object"||Array.isArray(cfg))throw Error("Ungültige Datei");localStorage.setItem("tb-admin-studio",JSON.stringify({...studioDefaults,...cfg}));applyStudio();$("studioMsg").textContent="Einstellungen importiert ✓"}catch(err){$("studioMsg").textContent="Import fehlgeschlagen: "+err.message}e.target.value=""};$("studioShortcut").onclick=()=>location.href="./studio.html";$("admin").onclick=async()=>{$("adminDialog").showModal();applyStudio();loadAnnouncement();try{let s=await api("/api/admin/stats");$("adminStats").textContent="Accounts: "+s.users+" · Chats: "+s.chats}catch(e){$("adminStats").textContent=e.message}loadMetrics();loadMaintenanceControl();loadDailyQuotaAdmin();loadAdminUsers()};$("saveAnnouncement").onclick=async()=>{const msg=$("announcementMsg"),btn=$("saveAnnouncement");btn.disabled=true;try{const r=await api("/api/admin/announcement",{method:"PUT",body:JSON.stringify({message:$("announcementInput").value})});msg.textContent=r.message;await loadSystemNotice()}catch(e){msg.textContent=e.message}finally{btn.disabled=false}};
