$("refreshMetrics").onclick=loadMetrics;$("closeAdmin").onclick=()=>$("adminDialog").close();$("loadTickets").onclick=loadAdminTickets;

let adminUsersCache=[];
function renderAdminUsers(){const el=$("adminUsers"),summary=$("adminUserSummary"),q=($("adminUserSearch").value||"").trim().toLowerCase();const filtered=adminUsersCache.filter(u=>String(u.id).includes(q)||u.username.toLowerCase().includes(q));summary.textContent=filtered.length+" von "+adminUsersCache.length+" Accounts · "+adminUsersCache.filter(u=>u.role==="admin").length+" Admins";el.innerHTML="";if(!filtered.length){el.textContent=q?"Keine passenden Accounts gefunden.":"Keine Benutzer.";return}filtered.forEach(u=>{const row=document.createElement("div");row.className="adminUserRow";const info=document.createElement("div"),name=document.createElement("strong"),meta=document.createElement("small");name.textContent="@"+u.username;meta.textContent="ID "+u.id+" · "+(u.role==="admin"?"Administrator":"Nutzer");info.append(name,meta);const select=document.createElement("select");select.setAttribute("aria-label","Rolle für "+u.username);[["user","Nutzer"],["admin","Admin"]].forEach(([v,l])=>{const o=document.createElement("option");o.value=v;o.textContent=l;o.selected=u.role===v;select.append(o)});select.disabled=Number(u.id)===Number(user.id);select.onchange=async()=>{const previous=u.role;select.disabled=true;try{await api("/api/admin/users/"+u.id+"/role",{method:"PUT",body:JSON.stringify({role:select.value})});u.role=select.value;$("usersMsg").textContent="@"+u.username+" ist jetzt "+(select.value==="admin"?"Admin":"Nutzer")+".";renderAdminUsers()}catch(e){$("usersMsg").textContent=e.message;select.value=previous;select.disabled=Number(u.id)===Number(user.id)}};row.append(info,select);el.append(row)})}
async function loadAdminUsers(){const el=$("adminUsers"),msg=$("usersMsg");el.textContent="Benutzer werden geladen …";msg.textContent="";try{adminUsersCache=await api("/api/admin/users");renderAdminUsers()}catch(e){el.textContent="Fehler: "+e.message;$("adminUserSummary").textContent=""}}
